  "Recommended: installs the Habblaud mod in Claude Code (2.1.287 or newer), which streams 5 h and weekly usage live. Run it in the Habblaud folder, on the computer where Claude Code runs; in sessions already open, `/reload-plugins`.": "Khuyến nghị: cài đặt bản mod Habblaud trong Claude Code (2.1.287 trở lên), phát trực tiếp mức sử dụng 5 giờ và hàng tuần. Chạy lệnh này trong thư mục Habblaud, trên máy tính đang chạy Claude Code; trong các phiên đã mở, gõ `/reload-plugins`.",
  "On Claude Code older than 2.1.287: hooks a tap into the status line, which streams the same numbers live.": "Trên Claude Code cũ hơn 2.1.287: gắn một tap vào dòng trạng thái để phát trực tiếp các số liệu tương tự.",
  "Without installing anything: run `/usage` in Claude Code on this account to refresh the cache (the numbers go stale until the next time).": "Không cần cài đặt gì: chạy `/usage` trong Claude Code trên tài khoản này để làm mới bộ nhớ đệm (các số liệu sẽ cũ dần cho đến lần tiếp theo).",
