  "At the last reading ({0}), the account had no quota or credits left to use (e.g. the workspace credits ran out). It's not 0%: Codex didn't report the windows. The numbers come back with the next session.": "Ở lần đọc gần nhất ({0}), tài khoản không còn hạn mức hoặc credit để sử dụng (ví dụ: đã hết credit của workspace). Đây không phải là 0%: Codex không báo cáo các khung thời gian. Các số liệu sẽ quay lại ở phiên tiếp theo.",
  "Codex only records usage while a session is running: these numbers are from the last reading ({0}).": "Codex chỉ ghi nhận mức sử dụng khi một phiên đang chạy: các số liệu này là từ lần đọc gần nhất ({0}).",
