  "Couldn't write {0}: {1}.": "Không thể ghi {0}: {1}.",
  "⬆️  New Habblaud version: v{0} (running: v{1}). What's new: {2}": "⬆️  Phiên bản Habblaud mới: v{0} (đang chạy: v{1}). Có gì mới: {2}",
  "GitHub didn't respond in time": "GitHub không phản hồi kịp thời",
  "no connection to GitHub": "không có kết nối tới GitHub",
  "--port needs a number between 1 and 65535.": "--port cần một số từ 1 đến 65535.",
  "unknown option: {0}\n\n{1}": "tùy chọn không xác định: {0}\n\n{1}",
  "message without id": "tin nhắn không có id",
  "empty message": "tin nhắn trống",
