  "{0} was already installed and stays ({1} doesn't remove it; to remove it: claude plugin uninstall {2})": "{0} đã được cài đặt trước đó và giữ nguyên ({1} không xóa mục này; để xóa: claude plugin uninstall {2})",
  "{0}: removed": "{0}: đã xóa",
