  "the file changed since it was read; nothing was changed, run the command again": "tệp đã thay đổi kể từ khi đọc; không có gì thay đổi, hãy chạy lại lệnh",
  "~ ~/.{0} (old name) goes to ~/.habblaud (dry run: nothing moved)": "~ ~/.{0} (tên cũ) chuyển tới ~/.habblaud (dry run: không có gì được di chuyển)",
