  "no usage captured yet (Claude Code sends the limits after the first reply in an open session)": "chưa ghi nhận mức sử dụng nào (Claude Code gửi các hạn mức sau câu trả lời đầu tiên trong một phiên đang mở)",
  "no usage captured": "chưa ghi nhận mức sử dụng nào",
  "Done. The numbers show up in Habblaud after each session's next reply. Sessions that are already": "Hoàn tất. Các con số sẽ hiển thị trong Habblaud sau câu trả lời tiếp theo của từng phiên. Các phiên đang",
  "open usually reload settings.json on their own; if usage doesn't show up, reopen the session.": "mở thường tự tải lại settings.json; nếu mức sử dụng không hiển thị, hãy mở lại phiên.",
  "Usage captured in {0}. To undo: npm run usage:uninstall": "Mức sử dụng được ghi lại trong {0}. Để hoàn tác: npm run usage:uninstall",
  "[usage] Error: {0}": "[usage] Lỗi: {0}",
