  "Usage: npm run codex:bridge [-- options]\n\nDelivers office messages to Codex sessions when Habblaud runs in Docker (keep it running on the computer).\n\nOptions:\n  --port <n>   Habblaud port (default: HABBLAUD_PORT or {0})\n  --once       runs a single pass and exits\n  -h, --help   shows this help\n\nCodex binary: HABBLAUD_CODEX_BIN or `codex` from PATH.": "Cách dùng: npm run codex:bridge [-- tùy chọn]\n\nChuyển tin nhắn văn phòng tới các phiên Codex khi Habblaud chạy trong Docker (hãy duy trì chạy trên máy tính).\n\nTùy chọn:\n  --port <n>   Cổng Habblaud (mặc định: HABBLAUD_PORT hoặc {0})\n  --once       chạy một lượt rồi thoát\n  -h, --help   hiển thị trợ giúp này\n\nFile nhị phân Codex: HABBLAUD_CODEX_BIN hoặc `codex` từ PATH.",
