  "✓ new agent in {0} running in the background with 1 attachment": "✓ agent mới tại {0} đang chạy ngầm với 1 tệp đính kèm",
  "✓ new agent in {0} opened in the Claude app (didn't run on its own: {1})": "✓ agent mới tại {0} đã mở trong ứng dụng Claude (không thể tự chạy: {1})",
  "✓ new agent in {0} opened in the Claude app with {1} attachments (didn't run on its own: {2})": "✓ agent mới tại {0} đã mở trong ứng dụng Claude với {1} tệp đính kèm (không thể tự chạy: {2})",
  "✓ new agent in {0} opened in the Claude app with 1 attachment (didn't run on its own: {1})": "✓ agent mới tại {0} đã mở trong ứng dụng Claude với 1 tệp đính kèm (không thể tự chạy: {1})",
  "✓ new agent in {0} opened in the Claude app": "✓ agent mới tại {0} đã mở trong ứng dụng Claude",
