  "✗ dictation: {0}": "✗ đọc chính tả: {0}",
  "outside the known project folders": "nằm ngoài các thư mục dự án đã biết",
  "✗ delivery file rejected: {0}": "✗ tệp bàn giao bị từ chối: {0}",
  "Delivering Habblaud messages (http://127.0.0.1:{0}) to Codex sessions with {1}, and starting the new agents requested in the office. Ctrl+C to stop.": "Đang chuyển tin nhắn Habblaud (http://127.0.0.1:{0}) đến các phiên Codex bằng {1}, và khởi động các agent mới được yêu cầu trong văn phòng. Nhấn Ctrl+C để dừng.",
  "No Codex (codex in PATH or HABBLAUD_CODEX_BIN): only starting the new agents requested in Habblaud (http://127.0.0.1:{0}). Ctrl+C to stop.": "Không có Codex (codex trong PATH hoặc HABBLAUD_CODEX_BIN): chỉ khởi động các agent mới được yêu cầu trong Habblaud (http://127.0.0.1:{0}). Nhấn Ctrl+C để dừng.",
  "New agents run in the background with {0} --bg (trusted folder; otherwise, in the Claude app).": "Các agent mới chạy ngầm bằng {0} --bg (thư mục tin cậy; nếu không, trong ứng dụng Claude).",
  "No claude in PATH (or HABBLAUD_CLAUDE_BIN): new agents open in the Claude app and wait for Enter.": "Không có claude trong PATH (hoặc HABBLAUD_CLAUDE_BIN): các agent mới mở trong ứng dụng Claude và chờ nhấn Enter.",
  "Dictation off: {0} is missing.": "Đọc chính tả đang tắt: thiếu {0}.",
  "Dictation: local Whisper ({0}), languages {1} auto-detected.": "Đọc chính tả: Whisper cục bộ ({0}), tự động nhận diện ngôn ngữ {1}.",
  "connected to Habblaud.": "đã kết nối với Habblaud.",
  "remote access configured, but no local CA: run npm run remote:setup.": "truy cập từ xa đã cấu hình nhưng chưa có CA cục bộ: hãy chạy npm run remote:setup.",
  "Remote access: server certificate renewed ({0}).": "Truy cập từ xa: chứng chỉ máy chủ đã được làm mới ({0}).",
  "Remote access: mounts {0} at {1}, read-only.": "Truy cập từ xa: gắn {0} tại {1}, chỉ đọc.",
  "remote access: couldn't check the certificate ({0}).": "truy cập từ xa: không thể kiểm tra chứng chỉ ({0}).",
  "Remote access: publishes {0} (container port {1}).": "Truy cập từ xa: công khai {0} (cổng container {1}).",
  "--timeout needs a number of seconds between 5 and 86400 (24 h).": "--timeout yêu cầu số giây từ 5 đến 86400 (24 giờ).",
  "[remote-mdns] no valid HABBLAUD_REMOTE_NAME in .env: run npm run remote:setup.": "[remote-mdns] không có HABBLAUD_REMOTE_NAME hợp lệ trong .env: hãy chạy npm run remote:setup.",
  "[remote-mdns] no network: announcement paused.": "[remote-mdns] không có mạng: tạm dừng phát thông báo.",
  "[remote-mdns] {0} not supported: use the IP or an address in the router's DNS.": "[remote-mdns] không hỗ trợ {0}: hãy dùng IP hoặc địa chỉ trong DNS của router.",
  "[remote-mdns] couldn't run {0}: {1}": "[remote-mdns] không thể chạy {0}: {1}",
  "[remote-mdns] announcing {0}.local -> {1}": "[remote-mdns] đang phát thông báo {0}.local -> {1}",
  "Usage: npm run remote:setup [-- options]\n\nTurns on phone access (https://<name>.local) with username, password and HTTPS.\n\n  --user <name>        login username (default: your system username)\n  --name <name>        address <name>.local (default: habblaud)\n  --domain <address>   own address, e.g. myclaude.home (needs an entry in the router's DNS)\n  --port <n>           port on the computer (default: 443 if free, otherwise 4748)\n  --allow <list>       what the phone can do: permissions, messages, terminal, spawn, none (default: permissions)\n  --password-stdin     reads the password from standard input (automation) instead of asking\n  --no-service         doesn't install the <name>.local announcement service (run npm run remote:mdns yourself)\n  --off                turns off phone access (removes the lines from .env and the service; keeps the CA)": "Cách dùng: npm run remote:setup [-- tùy chọn]\n\nBật tính năng truy cập điện thoại (https://<name>.local) với tên người dùng, mật khẩu và HTTPS.\n\n  --user <name>        tên người dùng đăng nhập (mặc định: tên người dùng hệ thống của bạn)\n  --name <name>        địa chỉ <name>.local (mặc định: habblaud)\n  --domain <address>   địa chỉ riêng, ví dụ: myclaude.home (cần một mục trong DNS của router)\n  --port <n>           cổng trên máy tính (mặc định: 443 nếu trống, nếu không là 4748)\n  --allow <list>       những gì điện thoại có thể làm: permissions, messages, terminal, spawn, none (mặc định: permissions)\n  --password-stdin     đọc mật khẩu từ đầu vào chuẩn (tự động hóa) thay vì hỏi\n  --no-service         không cài đặt dịch vụ phát thông báo <name>.local (tự chạy npm run remote:mdns)\n  --off                tắt truy cập điện thoại (xóa các dòng khỏi .env và dịch vụ; giữ lại CA)",
  "missing value for {0}": "thiếu giá trị cho {0}",
