  "Habblaud: announces the .local address for phone access": "Habblaud: phát thông báo địa chỉ .local để truy cập qua điện thoại",
  "habblaud-remote-mdns service enabled (to keep it on while logged out: loginctl enable-linger)": "đã bật dịch vụ habblaud-remote-mdns (để duy trì khi đã đăng xuất: loginctl enable-linger)",
  "{0}: no automatic service; keep npm run remote:mdns running or use the IP": "{0}: không có dịch vụ tự động; hãy duy trì npm run remote:mdns chạy hoặc dùng IP",
  "[remote-setup] Phone access turned off (the CA stays in ~/.habblaud/remote-tls). Now: npm run docker:up": "[remote-setup] Đã tắt truy cập điện thoại (CA vẫn ở trong ~/.habblaud/remote-tls). Bây giờ: npm run docker:up",
  "Login username": "Tên người dùng đăng nhập",
