  "Own address, optional (e.g. myclaude.home; Enter skips)": "Địa chỉ riêng, không bắt buộc (ví dụ: myclaude.home; nhấn Enter để bỏ qua)",
  "invalid address: \"{0}\"": "địa chỉ không hợp lệ: \"{0}\"",
  "[remote-setup] Generating the password hash…": "[remote-setup] Đang tạo hàm băm mật khẩu…",
  "service not installed (--no-service): run npm run remote:mdns": "dịch vụ chưa được cài đặt (--no-service): hãy chạy npm run remote:mdns",
  " New local CA (the address changed or the previous one had no name constraints): install the certificate on the phone again.": " CA cục bộ mới (địa chỉ đã thay đổi hoặc CA trước đó không có ràng buộc tên): hãy cài đặt lại chứng chỉ trên điện thoại.",
