  "  On the phone (same Wi-Fi):": "  Trên điện thoại (cùng Wi-Fi):",
  "  First time: accept the warning, tap \"Install the Habblaud certificate\" and trust it": "  Lần đầu: chấp nhận cảnh báo, chạm \"Cài đặt chứng chỉ Habblaud\" và cấp tin cậy",
  "    iPhone:  Settings > Profile Downloaded > Install; then Settings > General > About > Certificate Trust Settings": "    iPhone:  Cài đặt > Đã tải về hồ sơ > Cài đặt; sau đó Cài đặt > Cài đặt chung > Giới thiệu > Cài đặt tin cậy chứng nhận",
  "    Android: Settings > Security > Encryption & credentials > Install a certificate > CA certificate": "    Android: Cài đặt > Bảo mật > Mã hóa và thông tin xác thực > Cài đặt chứng chỉ > Chứng chỉ CA",
  "  CA fingerprint (check it on the phone before trusting it):": "  Vân tay CA (kiểm tra trên điện thoại trước khi cấp tin cậy):",
  "(unavailable)": "(không khả dụng)",
  "[remote-setup] Error: {0}": "[remote-setup] Lỗi: {0}",
  "Sign out": "Đăng xuất",
  "Phone access": "Truy cập điện thoại",
  "Sign out of this device": "Đăng xuất khỏi thiết bị này",
  "Ends the login here (a copy of the cookie stops working too). To come back, sign in with your username and password.": "Kết thúc đăng nhập tại đây (bản sao của cookie cũng sẽ ngừng hoạt động). Để quay lại, hãy đăng nhập bằng tên người dùng và mật khẩu của bạn.",
  "Doesn't go with this hair": "Không hợp với kiểu tóc này",
  "Doesn't go with the cap or beanie": "Không hợp với mũ lưỡi trai hoặc mũ len",
  "Doesn't go with the bow": "Không hợp với chiếc nơ",
  "I code late at night": "Tôi code đêm",
  "I get up early to code": "Tôi dậy sớm để code",
  "Powered by coffee": "Chạy bằng cà phê",
  "Team tea": "Team trà",
