  "Team spaces": "Team space",
  "Dark mode, always": "Dark mode, luôn luôn",
  "Light mode, no fear": "Light mode, chẳng ngại chi",
  "Vim till the end": "Vim tới cùng",
  "I test before I write": "Tôi viết test trước khi code",
