  "🥵 Boss overloaded": "🥵 Sếp quá tải",
  "These sessions have a long context or were compacted: they get slower and forget earlier details. The usual way out: ask for a handoff, then continue in a new session in the same folder.": "Các phiên này có context dài hoặc đã bị compact: chúng chậm hơn và quên chi tiết cũ. Cách thường dùng: yêu cầu viết handoff, rồi tiếp tục ở phiên mới trong cùng thư mục.",
